152	func (s *Store) UpdateIdentityProvider(ctx context.Context, update *UpdateIdentityProviderV1) (*storepb.IdentityProvider, error) {
153		updateRaw := &UpdateIdentityProvider{
154			ID: update.ID,
155		}
156		if update.Name != nil {
157			updateRaw.Name = update.Name
158		}
159		if update.IdentifierFilter != nil {
160			updateRaw.IdentifierFilter = update.IdentifierFilter
161		}
162		if update.Config != nil {
163			configRaw, err := convertIdentityProviderConfigToRaw(update.Type, update.Config)
164			if err != nil {
165				return nil, err
166			}
167			updateRaw.Config = &configRaw
168		}
169		identityProviderRaw, err := s.driver.UpdateIdentityProvider(ctx, updateRaw)
170		if err != nil {
171			return nil, err
172		}
173	
174		identityProvider, err := convertIdentityProviderFromRaw(identityProviderRaw)
175		if err != nil {
176			return nil, err
177		}
178		return identityProvider, nil
179	}
