189	func convertIdentityProviderFromRaw(raw *IdentityProvider) (*storepb.IdentityProvider, error) {
190		identityProvider := &storepb.IdentityProvider{
191			Id:               raw.ID,
192			Uid:              raw.UID,
193			Name:             raw.Name,
194			Type:             raw.Type,
195			IdentifierFilter: raw.IdentifierFilter,
196		}
197		config, err := convertIdentityProviderConfigFromRaw(identityProvider.Type, raw.Config)
198		if err != nil {
199			return nil, err
200		}
201		identityProvider.Config = config
202		return identityProvider, nil
203	}
204	
205	func convertIdentityProviderToRaw(identityProvider *storepb.IdentityProvider) (*IdentityProvider, error) {
206		raw := &IdentityProvider{
207			ID:               identityProvider.Id,
208			UID:              identityProvider.Uid,
209			Name:             identityProvider.Name,
210			Type:             identityProvider.Type,
211			IdentifierFilter: identityProvider.IdentifierFilter,
212		}
213		configRaw, err := convertIdentityProviderConfigToRaw(identityProvider.Type, identityProvider.Config)
214		if err != nil {
215			return nil, err
216		}
217		raw.Config = configRaw
218		return raw, nil
219	}
220	
221	func convertIdentityProviderConfigFromRaw(identityProviderType storepb.IdentityProvider_Type, raw string) (*storepb.IdentityProviderConfig, error) {
222		config := &storepb.IdentityProviderConfig{}
223		if identityProviderType == storepb.IdentityProvider_OAUTH2 {
224			oauth2Config := &storepb.OAuth2Config{}
225			if err := protojsonUnmarshaler.Unmarshal([]byte(raw), oauth2Config); err != nil {
226				return nil, errors.Wrap(err, "Failed to unmarshal OAuth2Config")
227			}
228			config.Config = &storepb.IdentityProviderConfig_Oauth2Config{Oauth2Config: oauth2Config}
229		}
230		return config, nil
231	}
232	
233	func convertIdentityProviderConfigToRaw(identityProviderType storepb.IdentityProvider_Type, config *storepb.IdentityProviderConfig) (string, error) {
234		raw := ""
235		if identityProviderType == storepb.IdentityProvider_OAUTH2 {
236			bytes, err := protojson.Marshal(config.GetOauth2Config())
237			if err != nil {
238				return "", errors.Wrap(err, "Failed to marshal OAuth2Config")
239			}
240			raw = string(bytes)
241		}
242		return raw, nil
243	}
