419	func convertUserSettingFromRaw(raw *UserSetting) (*storepb.UserSetting, error) {
420		userSetting := &storepb.UserSetting{
421			UserId: raw.UserID,
422			Key:    raw.Key,
423		}
424	
425		switch raw.Key {
426		case storepb.UserSetting_SHORTCUTS:
427			shortcutsUserSetting := &storepb.ShortcutsUserSetting{}
428			if err := protojsonUnmarshaler.Unmarshal([]byte(raw.Value), shortcutsUserSetting); err != nil {
429				return nil, err
430			}
431			userSetting.Value = &storepb.UserSetting_Shortcuts{Shortcuts: shortcutsUserSetting}
432		case storepb.UserSetting_GENERAL:
433			generalUserSetting := &storepb.GeneralUserSetting{}
434			if err := protojsonUnmarshaler.Unmarshal([]byte(raw.Value), generalUserSetting); err != nil {
435				return nil, err
436			}
437			userSetting.Value = &storepb.UserSetting_General{General: generalUserSetting}
438		case storepb.UserSetting_TAGS:
439			tagsUserSetting := &storepb.TagsUserSetting{}
440			if err := protojsonUnmarshaler.Unmarshal([]byte(raw.Value), tagsUserSetting); err != nil {
441				return nil, errors.Wrap(err, "unmarshal tags user setting")
442			}
443			userSetting.Value = &storepb.UserSetting_Tags{Tags: tagsUserSetting}
444		case storepb.UserSetting_REFRESH_TOKENS:
445			refreshTokensUserSetting := &storepb.RefreshTokensUserSetting{}
446			if err := protojsonUnmarshaler.Unmarshal([]byte(raw.Value), refreshTokensUserSetting); err != nil {
447				return nil, err
448			}
449			userSetting.Value = &storepb.UserSetting_RefreshTokens{RefreshTokens: refreshTokensUserSetting}
450		case storepb.UserSetting_PERSONAL_ACCESS_TOKENS:
451			patsUserSetting := &storepb.PersonalAccessTokensUserSetting{}
452			if err := protojsonUnmarshaler.Unmarshal([]byte(raw.Value), patsUserSetting); err != nil {
453				return nil, err
454			}
455			userSetting.Value = &storepb.UserSetting_PersonalAccessTokens{PersonalAccessTokens: patsUserSetting}
456		case storepb.UserSetting_WEBHOOKS:
457			webhooksUserSetting := &storepb.WebhooksUserSetting{}
458			if err := protojsonUnmarshaler.Unmarshal([]byte(raw.Value), webhooksUserSetting); err != nil {
459				return nil, err
460			}
461			userSetting.Value = &storepb.UserSetting_Webhooks{Webhooks: webhooksUserSetting}
462		default:
463			return nil, nil
464		}
465		return userSetting, nil
466	}
