68	func (s *Store) ListInstanceSettings(ctx context.Context, find *FindInstanceSetting) ([]*storepb.InstanceSetting, error) {
69		stored, err := s.listStoredInstanceSettings(ctx, find)
70		if err != nil {
71			return nil, err
72		}
73		if find.Name != "" {
74			key, ok := storepb.InstanceSettingKey_value[find.Name]
75			if ok {
76				if configured := s.getDeploymentInstanceSetting(storepb.InstanceSettingKey(key)); configured != nil {
77					return []*storepb.InstanceSetting{configured}, nil
78				}
79			}
80			return stored, nil
81		}
82	
83		byKey := make(map[storepb.InstanceSettingKey]*storepb.InstanceSetting, len(stored))
84		for _, setting := range stored {
85			byKey[setting.Key] = setting
86		}
87		s.deploymentConfigMu.RLock()
88		for key, setting := range s.deploymentConfig.instanceSettings {
89			byKey[key] = cloneInstanceSetting(setting)
90		}
91		s.deploymentConfigMu.RUnlock()
92		settings := make([]*storepb.InstanceSetting, 0, len(byKey))
93		for _, setting := range byKey {
94			settings = append(settings, setting)
95		}
96		slices.SortFunc(settings, func(a, b *storepb.InstanceSetting) int { return cmp.Compare(a.Key, b.Key) })
97		return settings, nil
98	}
