100	func (s *Store) listStoredInstanceSettings(ctx context.Context, find *FindInstanceSetting) ([]*storepb.InstanceSetting, error) {
101		list, err := s.driver.ListInstanceSettings(ctx, find)
102		if err != nil {
103			return nil, err
104		}
105	
106		instanceSettings := []*storepb.InstanceSetting{}
107		for _, instanceSettingRaw := range list {
108			instanceSetting, err := convertInstanceSettingFromRaw(instanceSettingRaw)
109			if err != nil {
110				return nil, errors.Wrap(err, "Failed to convert instance setting")
111			}
112			if instanceSetting == nil {
113				continue
114			}
115			s.cacheInstanceSetting(ctx, instanceSetting)
116			instanceSettings = append(instanceSettings, instanceSetting)
117		}
118		return instanceSettings, nil
119	}
